<?php
namespace Tests\Feature;
use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{DB,Http};use Illuminate\Support\Str;use App\Models\{Product,User,MarketingCampaign};
class MarketingQuoteAttributionTest extends TestCase{use RefreshDatabase;
 public function test_quote_submission_is_attributed_once_and_is_not_a_sale(){Http::preventStrayRequests();config(['product_enquiries.enabled'=>true,'marketing.attribution_enabled'=>true]);$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$merchant=app(\App\Services\Marketing\MarketingPosts::class)->merchant();$c=MarketingCampaign::create(['merchant_key'=>$merchant,'user_id'=>$u->id,'name'=>'Quote campaign','objective'=>'Get a quote','status'=>'Active','starts_on'=>'2026-01-01','ends_on'=>'2027-01-01','timezone'=>'UTC','destination_url'=>'http://localhost','cta'=>'Get a quote','version'=>1]);$link=(string)Str::uuid();DB::table('marketing_tracking_links')->insert(['id'=>$link,'campaign_id'=>$c->id,'post_id'=>(string)Str::uuid(),'destination_id'=>(string)Str::uuid(),'merchant_key'=>$merchant,'user_id'=>$u->id,'post_version'=>1,'destination_url'=>'http://localhost']);$p=Product::create(['title'=>'Quote item','handle'=>'quote-item','purchase_mode'=>'quote','price_display'=>'hide','status'=>'active','base_price'=>0]);$d=['product_id'=>$p->id,'request_key'=>(string)Str::uuid(),'name'=>'Test visitor','email'=>'test@example.test','requirements'=>'Please quote.'];$this->withSession(['marketing'=>['consent'=>true,'last'=>['id'=>$link,'at'=>now()->timestamp,'session'=>'test-session'],'first'=>['id'=>$link,'at'=>now()->timestamp,'session'=>'test-session']]])->post('/enquiries',$d)->assertRedirect();$this->post('/enquiries',$d)->assertRedirect();$this->assertDatabaseCount('marketing_enquiry_attributions',1);$this->assertDatabaseCount('marketing_order_attributions',0);Http::assertNothingSent();}
 public function test_later_quotation_payment_inherits_enquiry_source_and_refunds_do_not_duplicate(){Http::preventStrayRequests();$owner=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$merchant=app(\App\Services\Marketing\MarketingPosts::class)->merchant();$campaign=(string)Str::uuid();$link=(string)Str::uuid();$enquiry=(string)Str::uuid();DB::table('marketing_enquiry_attributions')->insert(['enquiry_id'=>$enquiry,'merchant_key'=>$merchant,'campaign_id'=>$campaign,'link_id'=>$link,'owner_id'=>$owner->id,'session_key'=>'session','clicked_at'=>now()->subDays(20),'submitted_at'=>now()->subDays(19)]);$order=\App\Models\Order::create(['number'=>'JW-Q-TEST','email'=>'guest@example.test','currency'=>'MYR','currency_exchange_rate'=>1,'status'=>'pending_payment','shipping_method'=>'quoted_manual','subtotal'=>10000,'discount_amount'=>0,'shipping_amount'=>0,'tax_amount'=>0,'total'=>10000]);$source=app(\App\Services\Marketing\MarketingAttribution::class);$source->inheritEnquiry($order,$enquiry);$source->inheritEnquiry($order,$enquiry);$this->assertDatabaseCount('marketing_order_attributions',1);$this->assertDatabaseHas('marketing_order_attributions',['order_id'=>$order->id,'campaign_id'=>$campaign,'state'=>'pending']);$payment=\App\Models\OrderPayment::create(['order_id'=>$order->id,'gateway'=>'bank_transfer','environment'=>'offline','status'=>'paid','proof_status'=>'verified','proof_reviewed_at'=>now(),'amount'=>10000,'currency'=>'MYR']);$service=app(\App\Services\Marketing\MarketingOrderEvidence::class);$service->reconcile($order->id);$service->reconcile($order->id);$this->assertDatabaseHas('marketing_order_attributions',['order_id'=>$order->id,'state'=>'paid','base_minor'=>10000]);\App\Models\OrderRefund::create(['order_id'=>$order->id,'order_payment_id'=>$payment->id,'user_id'=>$owner->id,'amount'=>2000,'reason'=>'Test partial refund','status'=>'completed']);$service->reconcile($order->id);$service->reconcile($order->id);$this->assertDatabaseHas('marketing_order_attributions',['order_id'=>$order->id,'refunded_minor'=>2000]);$this->assertDatabaseCount('marketing_order_attributions',1);Http::assertNothingSent();}
}
